// Builds the design tokens in tokens/ into every output that reads them: src/themes.css for the
// package, tokens/figma/<mode>.json for Figma and a docs page. Run `pnpm generate` after changing
// a token; the tokens test fails while a generated file is stale.
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import StyleDictionary from 'style-dictionary';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const TOKENS = join(ROOT, 'tokens');
const PREFIX = 's';
const MODES = ['light', 'dark'];
const DOCS_PAGE = '../../apps/docs/ui/tokens.md';
const CSS_FORMAT = 'surgijs/css-variables';
const FIGMA_FORMAT = 'surgijs/figma-dtcg';

const THEMES_HEADER = `/*
 * @surgijs/ui design tokens. Components read them through their own --s-<component>-*
 * properties, so a page can retheme everything here or override one component locally.
 *
 * Light is the default. \`data-theme="dark"\` on any ancestor switches to dark;
 * without a data-theme on the root, the OS preference picks the theme.
 *
 * Generated by scripts/tokens.mjs from tokens/*.json. Edit the tokens, then run \`pnpm generate\`.
 */`;

const SECTIONS = [
  ['font', 'Typography'],
  ['radius', 'Corners'],
  ['duration', 'Motion'],
  ['color', 'Color'],
];

const isColor = (token) => token.path[0] === 'color';

const sourcesOf = (mode) => [join(TOKENS, 'base.json'), join(TOKENS, `${mode}.json`)];

function cssVariables({ dictionary, options }) {
  const { selector, colorScheme, depth = 0 } = options;
  const pad = '  '.repeat(depth);
  const sections = [];
  if (colorScheme) sections.push([`color-scheme: ${colorScheme};`]);
  let group;
  for (const token of dictionary.allTokens) {
    if (token.path[0] !== group) {
      group = token.path[0];
      sections.push([]);
    }
    sections.at(-1).push(`--${token.name}: ${token.$value};`);
  }
  const body = sections
    .filter((lines) => lines.length > 0)
    .map((lines) => lines.map((line) => `${pad}  ${line}`).join('\n'))
    .join('\n\n');
  return `${pad}${selector} {\n${body}\n${pad}}`;
}

function figmaDtcg({ dictionary }) {
  const root = {};
  for (const token of dictionary.allTokens) {
    const parent = token.path.slice(0, -1).reduce((node, key) => (node[key] ??= {}), root);
    parent[token.path.at(-1)] = {
      $type: token.$type,
      $value: token.$value,
      ...(token.$description && { $description: token.$description }),
    };
  }
  return JSON.stringify(root, null, 2) + '\n';
}

async function cssBlock(mode, options, filter) {
  const sd = new StyleDictionary({
    source: sourcesOf(mode),
    log: { verbosity: 'silent' },
    hooks: { formats: { [CSS_FORMAT]: cssVariables } },
    platforms: {
      css: {
        transforms: ['name/kebab'],
        prefix: PREFIX,
        files: [{ destination: 'themes.css', format: CSS_FORMAT, filter, options }],
      },
    },
  });
  const [{ output }] = await sd.formatPlatform('css');
  return output;
}

async function themesCss() {
  const light = await cssBlock('light', { selector: ":root,\n[data-theme='light']", colorScheme: 'light' });
  const dark = await cssBlock('dark', { selector: "[data-theme='dark']", colorScheme: 'dark' }, isColor);
  const darkByOs = await cssBlock('dark', { selector: ':root:not([data-theme])', colorScheme: 'dark', depth: 1 }, isColor);
  return [THEMES_HEADER, light, dark, `@media (prefers-color-scheme: dark) {\n${darkByOs}\n}`].join('\n\n') + '\n';
}

async function figmaJson(mode) {
  const sd = new StyleDictionary({
    source: sourcesOf(mode),
    log: { verbosity: 'silent' },
    hooks: { formats: { [FIGMA_FORMAT]: figmaDtcg } },
    platforms: {
      figma: { files: [{ destination: `${mode}.json`, format: FIGMA_FORMAT }] },
    },
  });
  const [{ output }] = await sd.formatPlatform('figma');
  return output;
}

async function tokensOf(mode) {
  const sd = new StyleDictionary({
    source: sourcesOf(mode),
    log: { verbosity: 'silent' },
    platforms: { css: { transforms: ['name/kebab'], prefix: PREFIX } },
  });
  return (await sd.getPlatformTokens('css')).allTokens;
}

const swatch = (value) => `<span class="token-swatch" style="background:${value}"></span>`;

function docsMarkdown(light, dark) {
  const darkByName = new Map(dark.map((token) => [token.name, token]));
  const lines = [
    '<!-- Generated by packages/ui/scripts/tokens.mjs from packages/ui/tokens. Do not edit by hand. -->',
    '',
    '# Design tokens',
    '',
    'Every value in `@surgijs/ui/themes.css` comes from the token files in `packages/ui/tokens`, and the same files produce the Figma token sets in `packages/ui/tokens/figma`. A Figma variable takes the token path as its name, so `color/primary-hover` is `--s-color-primary-hover` in CSS.',
    '',
    'Light values apply by default. Dark values apply under `data-theme="dark"` or, without a `data-theme` on the root, when the OS prefers dark.',
    '',
  ];
  for (const [group, title] of SECTIONS) {
    lines.push(`## ${title}`, '');
    const tokens = light.filter((token) => token.path[0] === group);
    if (group === 'color') {
      lines.push('| Token | Light | Dark | Used for |', '| --- | --- | --- | --- |');
      for (const token of tokens) {
        const dark = darkByName.get(token.name);
        lines.push(
          `| \`--${token.name}\` | ${swatch(token.$value)} \`${token.$value}\` | ${swatch(dark.$value)} \`${dark.$value}\` | ${token.$description} |`,
        );
      }
    } else {
      lines.push('| Token | Value | Used for |', '| --- | --- | --- |');
      for (const token of tokens) {
        lines.push(`| \`--${token.name}\` | \`${token.$value}\` | ${token.$description} |`);
      }
    }
    lines.push('');
  }
  return lines.join('\n');
}

export async function generatedFiles() {
  const figma = await Promise.all(MODES.map(async (mode) => [`tokens/figma/${mode}.json`, await figmaJson(mode)]));
  const docs = docsMarkdown(await tokensOf('light'), await tokensOf('dark'));
  return { 'src/themes.css': await themesCss(), ...Object.fromEntries(figma), [DOCS_PAGE]: docs };
}

export async function generate() {
  for (const [file, contents] of Object.entries(await generatedFiles())) {
    const target = join(ROOT, file);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, contents);
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await generate();
